// Error hierarchy mirroring PyYAML's error classes and their string rendering.

const LINE_BREAK_CHARS = ['\0', '\r', '\n', '', ' ', ' '];

function isBreakChar(ch) {
  for (let i = 0; i < LINE_BREAK_CHARS.length; i++) {
    if (LINE_BREAK_CHARS[i] === ch) return true;
  }
  return false;
}

function repeat(str, count) {
  let out = '';
  for (let i = 0; i < count; i++) out += str;
  return out;
}

export class Mark {
  // `buffer` is an array of code points (see Reader), `pointer` an index into it.
  constructor(name, index, line, column, buffer, pointer) {
    this.name = name;
    this.index = index;
    this.line = line;
    this.column = column;
    this.buffer = buffer;
    this.pointer = pointer;
  }

  getSnippet(indent = 4, maxLength = 75) {
    if (this.buffer === null || this.buffer === undefined) return null;
    let head = '';
    let start = this.pointer;
    while (start > 0 && !isBreakChar(this.buffer[start - 1])) {
      start -= 1;
      if (this.pointer - start > maxLength / 2 - 1) {
        head = ' ... ';
        start += 5;
        break;
      }
    }
    let tail = '';
    let end = this.pointer;
    while (end < this.buffer.length && !isBreakChar(this.buffer[end])) {
      end += 1;
      if (end - this.pointer > maxLength / 2 - 1) {
        tail = ' ... ';
        end -= 5;
        break;
      }
    }
    const snippet = this.buffer.slice(start, end).join('');
    return repeat(' ', indent) + head + snippet + tail + '\n' +
      repeat(' ', indent + this.pointer - start + head.length) + '^';
  }

  toString() {
    const snippet = this.getSnippet();
    let where = '  in "' + this.name + '", line ' + (this.line + 1) +
      ', column ' + (this.column + 1);
    if (snippet !== null) where += ':\n' + snippet;
    return where;
  }
}

export class YAMLError extends Error {
  constructor(message) {
    super(message);
    this.pyClass = 'yaml.error.YAMLError';
  }
}

export class MarkedYAMLError extends YAMLError {
  constructor(context, contextMark, problem, problemMark, note) {
    super('');
    this.context = context === undefined ? null : context;
    this.contextMark = contextMark === undefined ? null : contextMark;
    this.problem = problem === undefined ? null : problem;
    this.problemMark = problemMark === undefined ? null : problemMark;
    this.note = note === undefined ? null : note;
    this.pyClass = 'yaml.error.MarkedYAMLError';
    this.message = this.render();
  }

  render() {
    const lines = [];
    if (this.context !== null) lines.push(this.context);
    if (this.contextMark !== null &&
        (this.problem === null || this.problemMark === null ||
         this.contextMark.name !== this.problemMark.name ||
         this.contextMark.line !== this.problemMark.line ||
         this.contextMark.column !== this.problemMark.column)) {
      lines.push(this.contextMark.toString());
    }
    if (this.problem !== null) lines.push(this.problem);
    if (this.problemMark !== null) lines.push(this.problemMark.toString());
    if (this.note !== null) lines.push(this.note);
    return lines.join('\n');
  }

  toString() {
    return this.render();
  }
}

export class ReaderError extends YAMLError {
  constructor(name, position, character, encoding, reason) {
    super('');
    this.name = name;
    this.position = position;
    this.character = character;
    this.encoding = encoding;
    this.reason = reason;
    this.pyClass = 'yaml.reader.ReaderError';
    this.message = this.render();
  }

  render() {
    let hex = this.character.codePointAt(0).toString(16);
    while (hex.length < 4) hex = '0' + hex;
    return 'unacceptable character #x' + hex + ': ' + this.reason +
      '\n  in "' + this.name + '", position ' + this.position;
  }

  toString() {
    return this.render();
  }
}

export class ScannerError extends MarkedYAMLError {
  constructor(context, contextMark, problem, problemMark, note) {
    super(context, contextMark, problem, problemMark, note);
    this.pyClass = 'yaml.scanner.ScannerError';
  }
}

export class ParserError extends MarkedYAMLError {
  constructor(context, contextMark, problem, problemMark, note) {
    super(context, contextMark, problem, problemMark, note);
    this.pyClass = 'yaml.parser.ParserError';
  }
}

export class ComposerError extends MarkedYAMLError {
  constructor(context, contextMark, problem, problemMark, note) {
    super(context, contextMark, problem, problemMark, note);
    this.pyClass = 'yaml.composer.ComposerError';
  }
}

export class ConstructorError extends MarkedYAMLError {
  constructor(context, contextMark, problem, problemMark, note) {
    super(context, contextMark, problem, problemMark, note);
    this.pyClass = 'yaml.constructor.ConstructorError';
  }
}

export class EmitterError extends YAMLError {
  constructor(message) {
    super(message);
    this.pyClass = 'yaml.emitter.EmitterError';
  }
}

export class SerializerError extends YAMLError {
  constructor(message) {
    super(message);
    this.pyClass = 'yaml.serializer.SerializerError';
  }
}

export class RepresenterError extends YAMLError {
  constructor(message) {
    super(message);
    this.pyClass = 'yaml.representer.RepresenterError';
  }
}

