// Character classification helpers. Everything is implemented with explicit
// code point comparisons: no regular expressions are used anywhere.

export const NULL = '\0';

export function contains(str, ch) {
  if (ch === '' || ch === undefined || ch === null) return false;
  for (let i = 0; i < str.length; i++) {
    if (str[i] === ch) return true;
  }
  return false;
}

export function isDigit(ch) {
  return ch >= '0' && ch <= '9';
}

export function isHexDigit(ch) {
  return (ch >= '0' && ch <= '9') || (ch >= 'A' && ch <= 'F') || (ch >= 'a' && ch <= 'f');
}

export function isAsciiLetter(ch) {
  return (ch >= 'A' && ch <= 'Z') || (ch >= 'a' && ch <= 'z');
}

export function isAsciiAlnum(ch) {
  return isDigit(ch) || isAsciiLetter(ch);
}

// Characters allowed inside anchor names / tag handles (PyYAML uses the ASCII
// alphanumeric range plus '-' and '_').
export function isAnchorChar(ch) {
  return isAsciiAlnum(ch) || ch === '-' || ch === '_';
}

const URI_EXTRA = "-;/?:@&=+$,_.!~*'()[]%";

export function isUriChar(ch) {
  return isAsciiAlnum(ch) || contains(URI_EXTRA, ch);
}

export function isBreak(ch) {
  return ch === '\r' || ch === '\n' || ch === '' ||
    ch === ' ' || ch === ' ';
}

export function isBreakOrNull(ch) {
  return ch === '\0' || isBreak(ch);
}

export function isBlank(ch) {
  return ch === ' ' || ch === '\t';
}

export function isBlankOrBreak(ch) {
  return isBlank(ch) || isBreak(ch);
}

export function isBlankOrBreakOrNull(ch) {
  return ch === '\0' || isBlank(ch) || isBreak(ch);
}

export function isSpaceOrNull(ch) {
  return ch === '\0' || ch === ' ';
}

// Mirrors PyYAML's Reader.NON_PRINTABLE test (inverted): the set of code points
// a document is allowed to contain.
export function isPrintableChar(ch) {
  const cp = ch.codePointAt(0);
  if (cp === 0x09 || cp === 0x0a || cp === 0x0d || cp === 0x85) return true;
  if (cp >= 0x20 && cp <= 0x7e) return true;
  if (cp >= 0xa0 && cp <= 0xd7ff) return true;
  if (cp >= 0xe000 && cp <= 0xfffd) return true;
  if (cp >= 0x10000 && cp <= 0x10ffff) return true;
  return false;
}

// The emitter's notion of "printable" for scalar analysis: line breaks and the
// tab are handled separately, everything else outside this set is "special".
export function isEmitterPrintable(ch) {
  const cp = ch.codePointAt(0);
  if (cp >= 0x20 && cp <= 0x7e) return true;
  if (cp === 0x85) return true;
  if (cp >= 0xa0 && cp <= 0xd7ff) return true;
  if (cp >= 0xe000 && cp <= 0xfffd) return true;
  if (cp >= 0x10000 && cp <= 0x10ffff) return true;
  return false;
}

// Splits a JS string into an array of code points (astral characters stay whole,
// matching Python's per-code-point string indexing).
export function toCodePoints(str) {
  const out = [];
  for (let i = 0; i < str.length; i++) {
    const code = str.charCodeAt(i);
    if (code >= 0xd800 && code <= 0xdbff && i + 1 < str.length) {
      const next = str.charCodeAt(i + 1);
      if (next >= 0xdc00 && next <= 0xdfff) {
        out.push(str[i] + str[i + 1]);
        i += 1;
        continue;
      }
    }
    out.push(str[i]);
  }
  return out;
}

export function repeat(str, count) {
  let out = '';
  for (let i = 0; i < count; i++) out += str;
  return out;
}

// Case-insensitive ASCII lowercase (Python's str.lower() on ASCII scalars).
export function asciiLower(str) {
  let out = '';
  for (let i = 0; i < str.length; i++) {
    const ch = str[i];
    out += (ch >= 'A' && ch <= 'Z')
      ? String.fromCharCode(ch.charCodeAt(0) + 32)
      : ch;
  }
  return out;
}

export function startsWith(str, prefix) {
  if (prefix.length > str.length) return false;
  for (let i = 0; i < prefix.length; i++) {
    if (str[i] !== prefix[i]) return false;
  }
  return true;
}

export function removeChar(str, ch) {
  let out = '';
  for (let i = 0; i < str.length; i++) {
    if (str[i] !== ch) out += str[i];
  }
  return out;
}

