// Python numeric semantics: repr() of floats, and the int/float literal parsing
// rules used by PyYAML's constructors. No regular expressions.

import { isDigit } from './chars.mjs';

export function pyIntToString(value) {
  return value.toString();
}

// Digits + decimal exponent of the shortest round-tripping representation.
function shortestDigits(x) {
  // toExponential() without an argument yields the shortest digit string that
  // uniquely identifies the double.
  const s = Math.abs(x).toExponential();
  let mantissa = '';
  let expPart = '';
  let seenE = false;
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (ch === 'e' || ch === 'E') { seenE = true; continue; }
    if (seenE) expPart += ch; else mantissa += ch;
  }
  let digits = '';
  for (let i = 0; i < mantissa.length; i++) {
    if (mantissa[i] !== '.') digits += mantissa[i];
  }
  // Strip trailing zeros (they carry no information for the shortest form).
  let end = digits.length;
  while (end > 1 && digits[end - 1] === '0') end -= 1;
  digits = digits.slice(0, end);
  const exp = Number(expPart);
  return { digits: digits, decpt: exp + 1 };
}

function padExponent(exp) {
  const sign = exp < 0 ? '-' : '+';
  let abs = String(Math.abs(exp));
  if (abs.length < 2) abs = '0' + abs;
  return sign + abs;
}

// CPython's repr() for floats (shortest round-trip, '.0' suffix for integral
// values, exponent form when decpt <= -4 or decpt > 16).
export function pyFloatRepr(x) {
  if (Number.isNaN(x)) return 'nan';
  if (x === Infinity) return 'inf';
  if (x === -Infinity) return '-inf';
  const negative = x < 0 || Object.is(x, -0);
  const sign = negative ? '-' : '';
  if (x === 0) return sign + '0.0';
  const info = shortestDigits(x);
  const digits = info.digits;
  const decpt = info.decpt;
  if (decpt <= -4 || decpt > 16) {
    let mantissa = digits[0];
    if (digits.length > 1) mantissa += '.' + digits.slice(1);
    return sign + mantissa + 'e' + padExponent(decpt - 1);
  }
  if (decpt <= 0) {
    let zeros = '';
    for (let i = 0; i < -decpt; i++) zeros += '0';
    return sign + '0.' + zeros + digits;
  }
  if (decpt >= digits.length) {
    let zeros = '';
    for (let i = 0; i < decpt - digits.length; i++) zeros += '0';
    return sign + digits + zeros + '.0';
  }
  return sign + digits.slice(0, decpt) + '.' + digits.slice(decpt);
}

// Python's float(str) for the shapes YAML's resolver can produce.
export function pyParseFloat(text) {
  if (text === '') return NaN;
  const value = Number(text);
  return value;
}

const DIGIT_VALUES = '0123456789abcdefghijklmnopqrstuvwxyz';

function digitValue(ch) {
  const lower = (ch >= 'A' && ch <= 'Z')
    ? String.fromCharCode(ch.charCodeAt(0) + 32)
    : ch;
  for (let i = 0; i < DIGIT_VALUES.length; i++) {
    if (DIGIT_VALUES[i] === lower) return i;
  }
  return -1;
}

// Python's int(str, base) restricted to the digits YAML allows. Returns a BigInt.
export function pyParseInt(text, base) {
  const radix = BigInt(base);
  let result = 0n;
  let any = false;
  for (let i = 0; i < text.length; i++) {
    const value = digitValue(text[i]);
    if (value < 0 || value >= base) {
      throw new Error("invalid literal for int() with base " + base + ": '" + text + "'");
    }
    result = result * radix + BigInt(value);
    any = true;
  }
  if (!any) {
    throw new Error("invalid literal for int() with base " + base + ": '" + text + "'");
  }
  return result;
}

export function allDigits(text) {
  if (text.length === 0) return false;
  for (let i = 0; i < text.length; i++) {
    if (!isDigit(text[i])) return false;
  }
  return true;
}

