// values, exponent form when decpt <= -4 or decpt > 16).
export function pyFloatRepr(x) {
  if (Number.isNaN(x)) return 'nan';
  if (x === Infinity) return 'inf';
  if (x === -Infinity) return '-inf';
  const negative = x < 0 || Object.is(x, -0);
  const sign = negative ? '-' : '';
  if (x === 0) return sign + '0.0';
  const info = shortestDigits(x);
  const digits = info.digits;
  const decpt = info.decpt;
  if (decpt <= -4 || decpt > 16) {
    let mantissa = digits[0];
    if (digits.length > 1) mantissa += '.' + digits.slice(1);
    return sign + mantissa + 'e' + padExponent(decpt - 1);
  }
  if (decpt <= 0) {
    let zeros = '';
    for (let i = 0; i < -decpt; i++) zeros += '0';
    return sign + '0.' + zeros + digits;
  }
  if (decpt >= digits.length) {
    let zeros = '';
    for (let i = 0; i < decpt - digits.length; i++) zeros += '0';
    return sign + digits + zeros + '.0';
  }
  return sign + digits.slice(0, decpt) + '.' + digits.slice(decpt);
}

