export function pyParseFloat(text) {
  if (text === '') return NaN;
  const value = Number(text);
  return value;
}

const DIGIT_VALUES = '0123456789abcdefghijklmnopqrstuvwxyz';

function digitValue(ch) {
  const lower = (ch >= 'A' && ch <= 'Z')
    ? String.fromCharCode(ch.charCodeAt(0) + 32)
    : ch;
  for (let i = 0; i < DIGIT_VALUES.length; i++) {
    if (DIGIT_VALUES[i] === lower) return i;
  }
