export function pyParseInt(text, base) {
  const radix = BigInt(base);
  let result = 0n;
  let any = false;
  for (let i = 0; i < text.length; i++) {
    const value = digitValue(text[i]);
    if (value < 0 || value >= base) {
      throw new Error("invalid literal for int() with base " + base + ": '" + text + "'");
