  }
  if (!any) {
    throw new Error("invalid literal for int() with base " + base + ": '" + text + "'");
  }
  return result;
}

export function allDigits(text) {
  if (text.length === 0) return false;
  for (let i = 0; i < text.length; i++) {
    if (!isDigit(text[i])) return false;
  }
  return true;
}

