// The Python object model that PyYAML loads into: bytes, tuples, ordered dicts,
// sets, dates and datetimes, plus Python's hashing / equality / ordering rules.
//
// Mapping of Python types onto JS values:
//   None -> null            str  -> string        int   -> BigInt
//   bool -> boolean         float-> number        list  -> Array
//   tuple -> PyTuple        dict -> PyDict        set   -> PySet
//   bytes -> PyBytes        date -> PyDate        datetime -> PyDateTime

import { pyFloatRepr } from './pynum.mjs';
import { toCodePoints } from './chars.mjs';

export class PyTypeError extends Error {}
export class PyValueError extends Error {}
export class UnhashableError extends Error {}

export class PyTuple {
  constructor(items) {
    this.items = items;
  }
}

export class PyBytes {
  constructor(data) {
    this.data = data; // Uint8Array
  }
}

export class PySet {
  constructor() {
    this.dict = new PyDict();
  }
  add(value) {
    this.dict.set(value, null);
  }
  values() {
    return this.dict.keys();
  }
  get size() {
    return this.dict.size;
  }
}

export class PyDict {
  constructor() {
    this._keys = [];
    this._values = [];
    this._index = new Map();
    this._nanCounter = 0;
  }

  get size() {
    return this._keys.length;
  }

  _slot(key, forInsert) {
    if (typeof key === 'number' && Number.isNaN(key)) {
      // Every NaN literal is a distinct object in Python, so it never collides.
      if (!forInsert) return undefined;
      this._nanCounter += 1;
      return 'nan#' + this._nanCounter;
    }
    return hashKey(key);
  }

  set(key, value) {
    const slot = this._slot(key, true);
    if (this._index.has(slot)) {
      this._values[this._index.get(slot)] = value;
      return;
    }
    this._index.set(slot, this._keys.length);
    this._keys.push(key);
    this._values.push(value);
  }

  get(key) {
    const slot = this._slot(key, false);
    if (slot === undefined || !this._index.has(slot)) return undefined;
    return this._values[this._index.get(slot)];
  }

  has(key) {
    const slot = this._slot(key, false);
    return slot !== undefined && this._index.has(slot);
  }

  keys() {
    return this._keys.slice();
  }

  items() {
    const out = [];
    for (let i = 0; i < this._keys.length; i++) {
      out.push([this._keys[i], this._values[i]]);
    }
    return out;
  }

  update(other) {
    const items = other.items();
    for (let i = 0; i < items.length; i++) this.set(items[i][0], items[i][1]);
  }
}

function pad(number, width) {
  let out = String(number);
  while (out.length < width) out = '0' + out;
  return out;
}

const DAYS_IN_MONTH = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

function isLeap(year) {
  return (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
}

function daysInMonth(year, month) {
  if (month === 2 && isLeap(year)) return 29;
  return DAYS_IN_MONTH[month - 1];
}

export function toOrdinal(year, month, day) {
  let days = 0;
  const y = year - 1;
  days += y * 365 + Math.floor(y / 4) - Math.floor(y / 100) + Math.floor(y / 400);
  for (let m = 1; m < month; m++) days += daysInMonth(year, m);
  return days + day;
}

function validateDate(year, month, day) {
  if (!(year >= 1 && year <= 9999)) throw new PyValueError('year ' + year + ' is out of range');
  if (!(month >= 1 && month <= 12)) throw new PyValueError('month must be in 1..12');
  if (!(day >= 1 && day <= daysInMonth(year, month))) {
    throw new PyValueError('day is out of range for month');
  }
}

export class PyDate {
  constructor(year, month, day) {
    validateDate(year, month, day);
    this.year = year;
    this.month = month;
    this.day = day;
  }
  isoformat() {
    return pad(this.year, 4) + '-' + pad(this.month, 2) + '-' + pad(this.day, 2);
  }
  ordinal() {
    return toOrdinal(this.year, this.month, this.day);
  }
