export class PyDateTime {
  constructor(year, month, day, hour, minute, second, microsecond, tzMinutes) {
    validateDate(year, month, day);
    if (!(hour >= 0 && hour <= 23)) throw new PyValueError('hour must be in 0..23');
    if (!(minute >= 0 && minute <= 59)) throw new PyValueError('minute must be in 0..59');
    if (!(second >= 0 && second <= 59)) throw new PyValueError('second must be in 0..59');
    if (!(microsecond >= 0 && microsecond <= 999999)) {
      throw new PyValueError('microsecond must be in 0..999999');
    }
    this.year = year;
    this.month = month;
    this.day = day;
    this.hour = hour;
    this.minute = minute;
    this.second = second;
    this.microsecond = microsecond;
    this.tzMinutes = tzMinutes === undefined ? null : tzMinutes;
  }

  isoformat(sep) {
    const separator = sep === undefined ? 'T' : sep;
    let out = pad(this.year, 4) + '-' + pad(this.month, 2) + '-' + pad(this.day, 2) +
      separator + pad(this.hour, 2) + ':' + pad(this.minute, 2) + ':' + pad(this.second, 2);
    if (this.microsecond !== 0) out += '.' + pad(this.microsecond, 6);
    if (this.tzMinutes !== null) {
      const sign = this.tzMinutes < 0 ? '-' : '+';
      const abs = Math.abs(this.tzMinutes);
      out += sign + pad(Math.floor(abs / 60), 2) + ':' + pad(abs % 60, 2);
    }
    return out;
  }

  // Microseconds since the proleptic Gregorian epoch, normalised to UTC when aware.
  micros() {
    const days = BigInt(toOrdinal(this.year, this.month, this.day));
    let total = days * 86400000000n +
      BigInt(this.hour) * 3600000000n +
      BigInt(this.minute) * 60000000n +
      BigInt(this.second) * 1000000n +
      BigInt(this.microsecond);
    if (this.tzMinutes !== null) total -= BigInt(this.tzMinutes) * 60000000n;
    return total;
  }
}

function isNumeric(value) {
  return typeof value === 'bigint' || typeof value === 'number' || typeof value === 'boolean';
}

function numericAsFloat(value) {
  if (typeof value === 'boolean') return value ? 1 : 0;
  if (typeof value === 'bigint') return Number(value);
  return value;
}

function numericAsBigInt(value) {
  if (typeof value === 'boolean') return value ? 1n : 0n;
  if (typeof value === 'bigint') return value;
  return BigInt(Math.trunc(value));
}

export function hashKey(value) {
  if (value === null) return 'N';
  if (typeof value === 'boolean') return 'i' + (value ? '1' : '0');
  if (typeof value === 'bigint') return 'i' + value.toString();
  if (typeof value === 'number') {
    if (Number.isNaN(value)) return 'fnan';
    if (value === Infinity) return 'f+inf';
    if (value === -Infinity) return 'f-inf';
    if (Number.isInteger(value)) return 'i' + BigInt(value).toString();
