  }
  if (value instanceof PyTuple) {
    let out = 't' + value.items.length + '(';
    for (let i = 0; i < value.items.length; i++) {
      const sub = hashKey(value.items[i]);
      out += sub.length + ':' + sub;
    }
    return out + ')';
  }
