    return (value.tzMinutes === null ? 'Tn' : 'Ta') + value.micros().toString();
  }
  if (value instanceof PyDate) {
    return 'D' + value.ordinal();
  }
  throw new UnhashableError('unhashable type');
}

export function isHashable(value) {
  if (Array.isArray(value) || value instanceof PyDict || value instanceof PySet) return false;
  return true;
}

function compareCodePoints(a, b) {
  const left = toCodePoints(a);
  const right = toCodePoints(b);
  const n = Math.min(left.length, right.length);
  for (let i = 0; i < n; i++) {
    const x = left[i].codePointAt(0);
    const y = right[i].codePointAt(0);
    if (x !== y) return x < y ? -1 : 1;
  }
  if (left.length === right.length) return 0;
  return left.length < right.length ? -1 : 1;
}

export function pyEquals(a, b) {
  if (a === b) return true;
  if (isNumeric(a) && isNumeric(b)) {
    if (typeof a === 'number' && Number.isNaN(a)) return false;
    if (typeof b === 'number' && Number.isNaN(b)) return false;
    if (typeof a === 'bigint' && typeof b === 'bigint') return a === b;
    const fa = numericAsFloat(a);
    const fb = numericAsFloat(b);
    if (typeof a === 'bigint' || typeof b === 'bigint') {
      const other = typeof a === 'bigint' ? fb : fa;
      if (!Number.isFinite(other)) return false;
      if (!Number.isInteger(other)) return false;
      return numericAsBigInt(a) === numericAsBigInt(b);
    }
    return fa === fb;
  }
  if (typeof a === 'string' || typeof b === 'string') {
    return typeof a === 'string' && typeof b === 'string' && a === b;
  }
  if (a instanceof PyBytes && b instanceof PyBytes) {
    if (a.data.length !== b.data.length) return false;
    for (let i = 0; i < a.data.length; i++) {
      if (a.data[i] !== b.data[i]) return false;
    }
    return true;
  }
  if (a instanceof PyTuple && b instanceof PyTuple) {
    if (a.items.length !== b.items.length) return false;
    for (let i = 0; i < a.items.length; i++) {
      if (!pyEquals(a.items[i], b.items[i])) return false;
    }
    return true;
  }
  if (Array.isArray(a) && Array.isArray(b)) {
    if (a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) {
      if (!pyEquals(a[i], b[i])) return false;
    }
    return true;
  }
  if (a instanceof PyDateTime && b instanceof PyDateTime) {
    if ((a.tzMinutes === null) !== (b.tzMinutes === null)) return false;
    return a.micros() === b.micros();
  }
