        if (typeof a === 'bigint') return floatSide === Infinity;
        return floatSide === -Infinity;
      }
      const bigA = typeof a === 'bigint' ? a : BigInt(Math.floor(numericAsFloat(a)));
      const bigB = typeof b === 'bigint' ? b : BigInt(Math.floor(numericAsFloat(b)));
