    }
    return numericAsFloat(a) < numericAsFloat(b);
  }
  if (typeof a === 'string' && typeof b === 'string') {
    return compareCodePoints(a, b) < 0;
  }
  if (a instanceof PyBytes && b instanceof PyBytes) {
    const n = Math.min(a.data.length, b.data.length);
    for (let i = 0; i < n; i++) {
      if (a.data[i] !== b.data[i]) return a.data[i] < b.data[i];
    }
    return a.data.length < b.data.length;
  }
  if (a instanceof PyTuple && b instanceof PyTuple) {
    return sequenceLessThan(a.items, b.items);
  }
  if (Array.isArray(a) && Array.isArray(b)) {
    return sequenceLessThan(a, b);
  }
  if (a instanceof PyDateTime && b instanceof PyDateTime) {
    if ((a.tzMinutes === null) !== (b.tzMinutes === null)) {
      throw new PyTypeError("can't compare offset-naive and offset-aware datetimes");
    }
    return a.micros() < b.micros();
  }
  if (a instanceof PyDate && b instanceof PyDate) {
    if ((a instanceof PyDateTime) !== (b instanceof PyDateTime)) {
      throw new PyTypeError("can't compare datetime.datetime to datetime.date");
    }
    return a.ordinal() < b.ordinal();
  }
