}

function sequenceLessThan(a, b) {
  const n = Math.min(a.length, b.length);
  for (let i = 0; i < n; i++) {
    if (!pyEquals(a[i], b[i])) return pyLessThan(a[i], b[i]);
  }
  return a.length < b.length;
}

