// CPython's list.sort() (timsort) emulated closely enough that a comparison
// raising TypeError aborts at the same point Python would.

function countRun(items, lo, hi, lessThan) {
  if (lo + 1 === hi) return { length: 1, descending: false };
  let n = 2;
  let descending = false;
  if (lessThan(items[lo + 1], items[lo])) {
    descending = true;
    for (let p = lo + 2; p < hi; p++, n++) {
      if (!lessThan(items[p], items[p - 1])) break;
    }
  } else {
    for (let p = lo + 2; p < hi; p++, n++) {
      if (lessThan(items[p], items[p - 1])) break;
    }
  }
  return { length: n, descending: descending };
}

function reverseSlice(items, lo, hi) {
  hi -= 1;
  while (lo < hi) {
    const tmp = items[lo];
    items[lo] = items[hi];
    items[hi] = tmp;
    lo += 1;
    hi -= 1;
  }
}

function binarySort(items, lo, hi, start, lessThan) {
  if (lo === start) start += 1;
  for (; start < hi; start++) {
    const pivot = items[start];
    let l = lo;
    let r = start;
    do {
      const p = l + ((r - l) >> 1);
      if (lessThan(pivot, items[p])) r = p;
      else l = p + 1;
    } while (l < r);
    for (let p = start; p > l; p--) items[p] = items[p - 1];
    items[l] = pivot;
  }
}

function computeMinrun(n) {
  let r = 0;
  while (n >= 64) {
    r |= n & 1;
    n >>= 1;
  }
  return n + r;
}

function mergeRuns(items, lo, mid, hi, lessThan) {
  const left = items.slice(lo, mid);
  const right = items.slice(mid, hi);
  let i = 0;
  let j = 0;
  let k = lo;
  while (i < left.length && j < right.length) {
    if (lessThan(right[j], left[i])) {
      items[k++] = right[j++];
    } else {
      items[k++] = left[i++];
    }
  }
  while (i < left.length) items[k++] = left[i++];
  while (j < right.length) items[k++] = right[j++];
}

// Sorts in place. Any exception thrown by `lessThan` propagates (the caller is
// expected to discard the partially sorted copy, exactly like Python's
// `try: mapping = sorted(mapping) except TypeError: pass`).
export function pySort(items, lessThan) {
  const n = items.length;
  if (n < 2) return items;
  const minrun = computeMinrun(n);
  const runs = [];
  let lo = 0;
  while (lo < n) {
    const run = countRun(items, lo, n, lessThan);
    let runLength = run.length;
    if (run.descending) reverseSlice(items, lo, lo + runLength);
    if (runLength < minrun) {
      const force = Math.min(n - lo, minrun);
      binarySort(items, lo, lo + force, lo + runLength, lessThan);
      runLength = force;
    }
    runs.push([lo, lo + runLength]);
    lo += runLength;
  }
  while (runs.length > 1) {
    const b = runs.pop();
    const a = runs.pop();
    mergeRuns(items, a[0], a[1], b[1], lessThan);
    runs.push([a[0], b[1]]);
  }
  return items;
}

