// PyYAML's Reader: exposes the input as a stream of code points with marks,
// and rejects characters YAML forbids.

import { Mark, ReaderError } from './errors.mjs';
import { toCodePoints, isPrintableChar } from './chars.mjs';

export class Reader {
  constructor(text) {
    this.name = '<unicode string>';
    this.buffer = toCodePoints(text);
    this.buffer.push('\0');
    this.pointer = 0;
    this.index = 0;
    this.line = 0;
    this.column = 0;
    this.checkPrintable(text);
  }

  checkPrintable(text) {
    const chars = toCodePoints(text);
    for (let i = 0; i < chars.length; i++) {
      if (!isPrintableChar(chars[i])) {
        throw new ReaderError(this.name, i, chars[i], 'unicode',
          'special characters are not allowed');
      }
    }
  }

  peek(index) {
    const offset = index === undefined ? 0 : index;
    const position = this.pointer + offset;
    if (position >= this.buffer.length) return '\0';
    return this.buffer[position];
  }

  prefix(length) {
    const size = length === undefined ? 1 : length;
    let end = this.pointer + size;
    if (end > this.buffer.length) end = this.buffer.length;
    return this.buffer.slice(this.pointer, end).join('');
  }

  forward(length) {
    let count = length === undefined ? 1 : length;
    while (count > 0) {
      const ch = this.buffer[this.pointer];
      this.pointer += 1;
      this.index += 1;
      if (ch === '\n' || ch === '' || ch === ' ' ||
          ch === ' ' || (ch === '\r' && this.buffer[this.pointer] !== '\n')) {
        this.line += 1;
        this.column = 0;
      } else if (ch !== '﻿') {
        this.column += 1;
      }
      count -= 1;
    }
  }

  getMark() {
    return new Mark(this.name, this.index, this.line, this.column, this.buffer, this.pointer);
  }
}

