// Token objects produced by the scanner. `type` replaces PyYAML's class checks.

function makeToken(type, startMark, endMark, extra) {
  const token = { type: type, startMark: startMark, endMark: endMark };
  if (extra) {
    const keys = Object.keys(extra);
    for (let i = 0; i < keys.length; i++) token[keys[i]] = extra[keys[i]];
  }
  return token;
}

export const T = {
  STREAM_START: 'StreamStart',
  STREAM_END: 'StreamEnd',
  DIRECTIVE: 'Directive',
  DOCUMENT_START: 'DocumentStart',
  DOCUMENT_END: 'DocumentEnd',
  BLOCK_SEQUENCE_START: 'BlockSequenceStart',
  BLOCK_MAPPING_START: 'BlockMappingStart',
  BLOCK_END: 'BlockEnd',
  FLOW_SEQUENCE_START: 'FlowSequenceStart',
  FLOW_MAPPING_START: 'FlowMappingStart',
  FLOW_SEQUENCE_END: 'FlowSequenceEnd',
  FLOW_MAPPING_END: 'FlowMappingEnd',
  KEY: 'Key',
  VALUE: 'Value',
  BLOCK_ENTRY: 'BlockEntry',
  FLOW_ENTRY: 'FlowEntry',
  ALIAS: 'Alias',
  ANCHOR: 'Anchor',
  TAG: 'Tag',
  SCALAR: 'Scalar',
};

// Human readable names used in parser error messages.
export const TOKEN_IDS = {
  StreamStart: '<stream start>',
  StreamEnd: '<stream end>',
  Directive: '<directive>',
  DocumentStart: '<document start>',
  DocumentEnd: '<document end>',
  BlockSequenceStart: '<block sequence start>',
  BlockMappingStart: '<block mapping start>',
  BlockEnd: '<block end>',
  FlowSequenceStart: '[',
  FlowMappingStart: '{',
  FlowSequenceEnd: ']',
  FlowMappingEnd: '}',
  Key: '?',
  Value: ':',
  BlockEntry: '-',
  FlowEntry: ',',
  Alias: '<alias>',
  Anchor: '<anchor>',
  Tag: '<tag>',
  Scalar: '<scalar>',
};

export function streamStartToken(startMark, endMark, encoding) {
  return makeToken(T.STREAM_START, startMark, endMark, { encoding: encoding });
}
export function streamEndToken(startMark, endMark) {
  return makeToken(T.STREAM_END, startMark, endMark);
}
export function directiveToken(name, value, startMark, endMark) {
  return makeToken(T.DIRECTIVE, startMark, endMark, { name: name, value: value });
}
export function simpleToken(type, startMark, endMark) {
  return makeToken(type, startMark, endMark);
}
export function aliasToken(value, startMark, endMark) {
  return makeToken(T.ALIAS, startMark, endMark, { value: value });
}
export function anchorToken(value, startMark, endMark) {
  return makeToken(T.ANCHOR, startMark, endMark, { value: value });
}
export function tagToken(value, startMark, endMark) {
  return makeToken(T.TAG, startMark, endMark, { value: value });
}
export function scalarToken(value, plain, startMark, endMark, style) {
  return makeToken(T.SCALAR, startMark, endMark, {
    value: value,
    plain: plain,
    style: style === undefined ? null : style,
  });
}

