// Python's repr() for the short strings PyYAML interpolates into error messages.

import { toCodePoints } from './chars.mjs';

function hex(value, width) {
  let out = value.toString(16);
  while (out.length < width) out = '0' + out;
  return out;
}

function isReprPrintable(cp) {
  if (cp < 0x20 || cp === 0x7f) return false;
  if (cp < 0x7f) return true;
  // Everything Python considers printable above ASCII is reproduced verbatim;
  // the C1 range and the separators below are escaped.
  if (cp >= 0x80 && cp <= 0xa0) return false;
  if (cp === 0xad) return false;
  if (cp >= 0x2000 && cp <= 0x200f) return false;
  if (cp >= 0x2028 && cp <= 0x202f) return false;
  if (cp >= 0x205f && cp <= 0x206f) return false;
  if (cp === 0xfeff) return false;
  if (cp >= 0xd800 && cp <= 0xdfff) return false;
  return true;
}

export function pyRepr(text) {
  const chars = toCodePoints(text);
  let hasSingle = false;
  let hasDouble = false;
  for (let i = 0; i < chars.length; i++) {
    if (chars[i] === "'") hasSingle = true;
    if (chars[i] === '"') hasDouble = true;
  }
  const quote = (hasSingle && !hasDouble) ? '"' : "'";
  let out = quote;
  for (let i = 0; i < chars.length; i++) {
    const ch = chars[i];
    const cp = ch.codePointAt(0);
    if (ch === '\\') out += '\\\\';
    else if (ch === quote) out += '\\' + ch;
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else if (!isReprPrintable(cp)) {
      if (cp < 0x100) out += '\\x' + hex(cp, 2);
      else if (cp < 0x10000) out += '\\u' + hex(cp, 4);
      else out += '\\U' + hex(cp, 8);
    } else out += ch;
  }
  return out + quote;
}

