      if (this.addIndent(this.column)) {
        const mark = this.getMark();
        this.tokens.push(simpleToken(T.BLOCK_MAPPING_START, mark, mark));
      }
    }
    this.allowSimpleKey = !this.flowLevel;
    this.removePossibleSimpleKey();
    const startMark = this.getMark();
    this.forward();
    const endMark = this.getMark();
    this.tokens.push(simpleToken(T.KEY, startMark, endMark));
  }

  fetchValue() {
    if (this.possibleSimpleKeys.has(this.flowLevel)) {
      const key = this.possibleSimpleKeys.get(this.flowLevel);
      this.possibleSimpleKeys.delete(this.flowLevel);
      this.tokens.splice(key.tokenNumber - this.tokensTaken, 0,
        simpleToken(T.KEY, key.mark, key.mark));
      if (!this.flowLevel) {
        if (this.addIndent(key.column)) {
          this.tokens.splice(key.tokenNumber - this.tokensTaken, 0,
            simpleToken(T.BLOCK_MAPPING_START, key.mark, key.mark));
        }
      }
      this.allowSimpleKey = false;
    } else {
      if (!this.flowLevel) {
        if (!this.allowSimpleKey) {
          throw new ScannerError(null, null, 'mapping values are not allowed here',
            this.getMark());
        }
      }
      if (!this.flowLevel) {
        if (this.addIndent(this.column)) {
          const mark = this.getMark();
          this.tokens.push(simpleToken(T.BLOCK_MAPPING_START, mark, mark));
        }
      }
      this.allowSimpleKey = !this.flowLevel;
      this.removePossibleSimpleKey();
    }
    const startMark = this.getMark();
    this.forward();
    const endMark = this.getMark();
    this.tokens.push(simpleToken(T.VALUE, startMark, endMark));
  }

  fetchAlias() {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanAnchor(T.ALIAS));
  }

  fetchAnchor() {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanAnchor(T.ANCHOR));
  }

  fetchTag() {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanTag());
  }

  fetchLiteral() {
    this.fetchBlockScalar('|');
  }

  fetchFolded() {
    this.fetchBlockScalar('>');
  }

  fetchBlockScalar(style) {
    this.allowSimpleKey = true;
    this.removePossibleSimpleKey();
    this.tokens.push(this.scanBlockScalar(style));
  }

  fetchSingle() {
    this.fetchFlowScalar("'");
  }

  fetchDouble() {
    this.fetchFlowScalar('"');
  }

  fetchFlowScalar(style) {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanFlowScalar(style));
  }

  fetchPlain() {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanPlain());
  }

  // ---- checkers ----------------------------------------------------------

  checkDirective() {
    return this.column === 0;
  }

  checkDocumentStart() {
    if (this.column === 0) {
      if (this.prefix(3) === '---' && contains(BLANKS_BREAKS_NULL, this.peek(3))) {
        return true;
      }
    }
    return false;
  }

  checkDocumentEnd() {
    if (this.column === 0) {
      if (this.prefix(3) === '...' && contains(BLANKS_BREAKS_NULL, this.peek(3))) {
        return true;
      }
    }
    return false;
  }

  checkBlockEntry() {
    return contains(BLANKS_BREAKS_NULL, this.peek(1));
  }

  checkKey() {
    if (this.flowLevel) return true;
    return contains(BLANKS_BREAKS_NULL, this.peek(1));
  }

  checkValue() {
    if (this.flowLevel) return true;
    return contains(BLANKS_BREAKS_NULL, this.peek(1));
  }

  checkPlain() {
    const ch = this.peek();
    if (!contains("\0 \t\r\n  -?:,[]{}#&*!|>'\"%@`", ch)) return true;
    return !contains(BLANKS_BREAKS_NULL, this.peek(1)) &&
      (ch === '-' || (!this.flowLevel && (ch === '?' || ch === ':')));
  }

  // ---- scanners ----------------------------------------------------------

  scanToNextToken() {
    if (this.index === 0 && this.peek() === '﻿') this.forward();
    let found = false;
    while (!found) {
      while (this.peek() === ' ') this.forward();
      if (this.peek() === '#') {
        while (!contains(BREAKS_NULL, this.peek())) this.forward();
      }
      if (this.scanLineBreak()) {
        if (!this.flowLevel) this.allowSimpleKey = true;
      } else {
        found = true;
      }
    }
  }

  scanDirective() {
    const startMark = this.getMark();
    this.forward();
    const name = this.scanDirectiveName(startMark);
    let value = null;
    let endMark;
    if (name === 'YAML') {
      value = this.scanYamlDirectiveValue(startMark);
      endMark = this.getMark();
    } else if (name === 'TAG') {
      value = this.scanTagDirectiveValue(startMark);
      endMark = this.getMark();
    } else {
      endMark = this.getMark();
      while (!contains(BREAKS_NULL, this.peek())) this.forward();
    }
    this.scanDirectiveIgnoredLine(startMark);
    return directiveToken(name, value, startMark, endMark);
  }

  scanDirectiveName(startMark) {
    let length = 0;
    let ch = this.peek(length);
    while (isAnchorChar(ch)) {
      length += 1;
      ch = this.peek(length);
    }
    if (!length) {
      throw new ScannerError('while scanning a directive', startMark,
        'expected alphabetic or numeric character, but found ' + pyRepr(ch),
        this.getMark());
    }
    const value = this.prefix(length);
    this.forward(length);
    ch = this.peek();
    if (!contains(SPACE_BREAKS_NULL, ch)) {
      throw new ScannerError('while scanning a directive', startMark,
        'expected alphabetic or numeric character, but found ' + pyRepr(ch),
        this.getMark());
    }
    return value;
  }

  scanYamlDirectiveValue(startMark) {
    while (this.peek() === ' ') this.forward();
    const major = this.scanYamlDirectiveNumber(startMark);
    if (this.peek() !== '.') {
      throw new ScannerError('while scanning a directive', startMark,
        "expected a digit or '.', but found " + pyRepr(this.peek()), this.getMark());
    }
    this.forward();
    const minor = this.scanYamlDirectiveNumber(startMark);
    if (!contains(SPACE_BREAKS_NULL, this.peek())) {
      throw new ScannerError('while scanning a directive', startMark,
        "expected a digit or ' ', but found " + pyRepr(this.peek()), this.getMark());
    }
    return [major, minor];
  }

  scanYamlDirectiveNumber(startMark) {
    const ch = this.peek();
    if (!isDigit(ch)) {
      throw new ScannerError('while scanning a directive', startMark,
        'expected a digit, but found ' + pyRepr(ch), this.getMark());
    }
    let length = 0;
    while (isDigit(this.peek(length))) length += 1;
    const value = Number(this.prefix(length));
    this.forward(length);
    return value;
  }

  scanTagDirectiveValue(startMark) {
    while (this.peek() === ' ') this.forward();
    const handle = this.scanTagDirectiveHandle(startMark);
    while (this.peek() === ' ') this.forward();
    const prefix = this.scanTagDirectivePrefix(startMark);
    return [handle, prefix];
  }

  scanTagDirectiveHandle(startMark) {
    const value = this.scanTagHandle('directive', startMark);
    const ch = this.peek();
    if (ch !== ' ') {
      throw new ScannerError('while scanning a directive', startMark,
        "expected ' ', but found " + pyRepr(ch), this.getMark());
    }
    return value;
  }

  scanTagDirectivePrefix(startMark) {
    const value = this.scanTagUri('directive', startMark);
    const ch = this.peek();
    if (!contains(SPACE_BREAKS_NULL, ch)) {
      throw new ScannerError('while scanning a directive', startMark,
        "expected ' ', but found " + pyRepr(ch), this.getMark());
    }
    return value;
  }

  scanDirectiveIgnoredLine(startMark) {
    while (this.peek() === ' ') this.forward();
    if (this.peek() === '#') {
      while (!contains(BREAKS_NULL, this.peek())) this.forward();
    }
    const ch = this.peek();
    if (!contains(BREAKS_NULL, ch)) {
      throw new ScannerError('while scanning a directive', startMark,
        'expected a comment or a line break, but found ' + pyRepr(ch), this.getMark());
    }
    this.scanLineBreak();
  }

  scanAnchor(type) {
    const startMark = this.getMark();
    const indicator = this.peek();
    const name = indicator === '*' ? 'alias' : 'anchor';
    this.forward();
    let length = 0;
    let ch = this.peek(length);
    while (isAnchorChar(ch)) {
      length += 1;
      ch = this.peek(length);
    }
    if (!length) {
      throw new ScannerError('while scanning an ' + name, startMark,
        'expected alphabetic or numeric character, but found ' + pyRepr(ch),
        this.getMark());
    }
    const value = this.prefix(length);
    this.forward(length);
    ch = this.peek();
    if (!contains("\0 \t\r\n  ?:,]}%@`", ch)) {
      throw new ScannerError('while scanning an ' + name, startMark,
        'expected alphabetic or numeric character, but found ' + pyRepr(ch),
        this.getMark());
    }
    const endMark = this.getMark();
    return type === T.ALIAS
      ? aliasToken(value, startMark, endMark)
      : anchorToken(value, startMark, endMark);
  }

  scanTag() {
    const startMark = this.getMark();
    let ch = this.peek(1);
    let handle;
    let suffix;
    if (ch === '<') {
      handle = null;
      this.forward(2);
      suffix = this.scanTagUri('tag', startMark);
      if (this.peek() !== '>') {
        throw new ScannerError('while parsing a tag', startMark,
          "expected '>', but found " + pyRepr(this.peek()), this.getMark());
      }
      this.forward();
    } else if (contains(BLANKS_BREAKS_NULL, ch)) {
      handle = null;
      suffix = '!';
      this.forward();
    } else {
      let length = 1;
      let useHandle = false;
      while (!contains(SPACE_BREAKS_NULL, ch)) {
        if (ch === '!') {
          useHandle = true;
          break;
        }
        length += 1;
        ch = this.peek(length);
      }
      if (useHandle) {
        handle = this.scanTagHandle('tag', startMark);
      } else {
        handle = '!';
        this.forward();
      }
      suffix = this.scanTagUri('tag', startMark);
    }
    ch = this.peek();
    if (!contains(SPACE_BREAKS_NULL, ch)) {
      throw new ScannerError('while scanning a tag', startMark,
        "expected ' ', but found " + pyRepr(ch), this.getMark());
    }
    const endMark = this.getMark();
    return tagToken([handle, suffix], startMark, endMark);
  }

  scanBlockScalar(style) {
    const folded = style === '>';
    const chunks = [];
    const startMark = this.getMark();
    this.forward();
    const indicators = this.scanBlockScalarIndicators(startMark);
    const chomping = indicators[0];
    const increment = indicators[1];
    this.scanBlockScalarIgnoredLine(startMark);

    let minIndent = this.indent + 1;
    if (minIndent < 1) minIndent = 1;
    let breaks;
    let indent;
    let endMark;
    if (increment === null) {
      const scanned = this.scanBlockScalarIndentation();
      breaks = scanned[0];
      const maxIndent = scanned[1];
      endMark = scanned[2];
      indent = Math.max(minIndent, maxIndent);
    } else {
      indent = minIndent + increment - 1;
      const scanned = this.scanBlockScalarBreaks(indent);
      breaks = scanned[0];
      endMark = scanned[1];
    }
    let lineBreak = '';
    while (this.column === indent && this.peek() !== '\0') {
      for (let i = 0; i < breaks.length; i++) chunks.push(breaks[i]);
      const leadingNonSpace = this.peek() !== ' ' && this.peek() !== '\t';
      let length = 0;
      while (!contains(BREAKS_NULL, this.peek(length))) length += 1;
      chunks.push(this.prefix(length));
      this.forward(length);
      lineBreak = this.scanLineBreak();
      const scanned = this.scanBlockScalarBreaks(indent);
      breaks = scanned[0];
      endMark = scanned[1];
      if (this.column === indent && this.peek() !== '\0') {
        if (folded && lineBreak === '\n' && leadingNonSpace &&
            this.peek() !== ' ' && this.peek() !== '\t') {
          if (breaks.length === 0) chunks.push(' ');
        } else {
          chunks.push(lineBreak);
        }
      } else {
        break;
      }
    }
    if (chomping !== false) chunks.push(lineBreak);
    if (chomping === true) {
      for (let i = 0; i < breaks.length; i++) chunks.push(breaks[i]);
    }
    return scalarToken(chunks.join(''), false, startMark, endMark, style);
  }

  scanBlockScalarIndicators(startMark) {
    let chomping = null;
    let increment = null;
    let ch = this.peek();
    if (ch === '+' || ch === '-') {
      chomping = ch === '+';
      this.forward();
      ch = this.peek();
      if (isDigit(ch)) {
        increment = Number(ch);
        if (increment === 0) {
          throw new ScannerError('while scanning a block scalar', startMark,
            'expected indentation indicator in the range 1-9, but found 0',
            this.getMark());
        }
        this.forward();
      }
    } else if (isDigit(ch)) {
      increment = Number(ch);
      if (increment === 0) {
        throw new ScannerError('while scanning a block scalar', startMark,
          'expected indentation indicator in the range 1-9, but found 0',
          this.getMark());
      }
      this.forward();
      ch = this.peek();
      if (ch === '+' || ch === '-') {
        chomping = ch === '+';
        this.forward();
      }
    }
    ch = this.peek();
    if (!contains(SPACE_BREAKS_NULL, ch)) {
      throw new ScannerError('while scanning a block scalar', startMark,
        'expected chomping or indentation indicators, but found ' + pyRepr(ch),
        this.getMark());
    }
    return [chomping, increment];
  }

  scanBlockScalarIgnoredLine(startMark) {
    while (this.peek() === ' ') this.forward();
    if (this.peek() === '#') {
      while (!contains(BREAKS_NULL, this.peek())) this.forward();
    }
    const ch = this.peek();
    if (!contains(BREAKS_NULL, ch)) {
      throw new ScannerError('while scanning a block scalar', startMark,
        'expected a comment or a line break, but found ' + pyRepr(ch), this.getMark());
    }
    this.scanLineBreak();
  }

  scanBlockScalarIndentation() {
    const chunks = [];
    let maxIndent = 0;
    let endMark = this.getMark();
    while (contains(' \r\n  ', this.peek())) {
      if (this.peek() !== ' ') {
        chunks.push(this.scanLineBreak());
        endMark = this.getMark();
      } else {
        this.forward();
        if (this.column > maxIndent) maxIndent = this.column;
      }
    }
    return [chunks, maxIndent, endMark];
  }

  scanBlockScalarBreaks(indent) {
    const chunks = [];
    let endMark = this.getMark();
    while (this.column < indent && this.peek() === ' ') this.forward();
    while (contains(BREAKS, this.peek())) {
      chunks.push(this.scanLineBreak());
      endMark = this.getMark();
      while (this.column < indent && this.peek() === ' ') this.forward();
    }
    return [chunks, endMark];
  }

  scanFlowScalar(style) {
    const double = style === '"';
    const chunks = [];
    const startMark = this.getMark();
    const quote = this.peek();
    this.forward();
    let part = this.scanFlowScalarNonSpaces(double, startMark);
    for (let i = 0; i < part.length; i++) chunks.push(part[i]);
    while (this.peek() !== quote) {
      part = this.scanFlowScalarSpaces(double, startMark);
      for (let i = 0; i < part.length; i++) chunks.push(part[i]);
      part = this.scanFlowScalarNonSpaces(double, startMark);
      for (let i = 0; i < part.length; i++) chunks.push(part[i]);
    }
    this.forward();
    const endMark = this.getMark();
    return scalarToken(chunks.join(''), false, startMark, endMark, style);
  }

  scanFlowScalarNonSpaces(double, startMark) {
    const chunks = [];
    for (;;) {
      let length = 0;
      while (!contains("'\"\\\0 \t\r\n  ", this.peek(length))) {
        length += 1;
      }
      if (length) {
        chunks.push(this.prefix(length));
        this.forward(length);
      }
      let ch = this.peek();
      if (!double && ch === "'" && this.peek(1) === "'") {
        chunks.push("'");
        this.forward(2);
      } else if ((double && ch === "'") || (!double && (ch === '"' || ch === '\\'))) {
        chunks.push(ch);
        this.forward();
      } else if (double && ch === '\\') {
        this.forward();
        ch = this.peek();
        if (ESCAPE_REPLACEMENTS.has(ch)) {
          chunks.push(ESCAPE_REPLACEMENTS.get(ch));
          this.forward();
        } else if (ESCAPE_CODES.has(ch)) {
          length = ESCAPE_CODES.get(ch);
          this.forward();
          for (let k = 0; k < length; k++) {
            if (!isHexDigit(this.peek(k))) {
              throw new ScannerError('while scanning a double-quoted scalar', startMark,
                'expected escape sequence of ' + length +
                ' hexadecimal numbers, but found ' + pyRepr(this.peek(k)),
                this.getMark());
            }
          }
          const code = Number.parseInt(this.prefix(length), 16);
          chunks.push(codePointToString(code, startMark, this));
          this.forward(length);
        } else if (contains(BREAKS, ch)) {
          this.scanLineBreak();
          const breaks = this.scanFlowScalarBreaks(double, startMark);
          for (let i = 0; i < breaks.length; i++) chunks.push(breaks[i]);
        } else {
          throw new ScannerError('while scanning a double-quoted scalar', startMark,
            'found unknown escape character ' + pyRepr(ch), this.getMark());
        }
      } else {
        return chunks;
      }
    }
  }

  scanFlowScalarSpaces(double, startMark) {
    const chunks = [];
    let length = 0;
    while (contains(' \t', this.peek(length))) length += 1;
    const whitespaces = this.prefix(length);
    this.forward(length);
    const ch = this.peek();
    if (ch === '\0') {
      throw new ScannerError('while scanning a quoted scalar', startMark,
        'found unexpected end of stream', this.getMark());
    } else if (contains(BREAKS, ch)) {
      const lineBreak = this.scanLineBreak();
      const breaks = this.scanFlowScalarBreaks(double, startMark);
      if (lineBreak !== '\n') chunks.push(lineBreak);
      else if (breaks.length === 0) chunks.push(' ');
      for (let i = 0; i < breaks.length; i++) chunks.push(breaks[i]);
    } else {
      chunks.push(whitespaces);
    }
    return chunks;
  }

  scanFlowScalarBreaks(double, startMark) {
    const chunks = [];
    for (;;) {
      const prefix = this.prefix(3);
      if ((prefix === '---' || prefix === '...') &&
          contains(BLANKS_BREAKS_NULL, this.peek(3))) {
        throw new ScannerError('while scanning a quoted scalar', startMark,
          'found unexpected document separator', this.getMark());
      }
      while (contains(' \t', this.peek())) this.forward();
      if (contains(BREAKS, this.peek())) {
        chunks.push(this.scanLineBreak());
      } else {
        return chunks;
      }
    }
  }

  scanPlain() {
    const chunks = [];
    const startMark = this.getMark();
    let endMark = startMark;
    const indent = this.indent + 1;
    let spaces = [];
    for (;;) {
      let length = 0;
      if (this.peek() === '#') break;
      for (;;) {
        const ch = this.peek(length);
        const valueTerminators = this.flowLevel
          ? BLANKS_BREAKS_NULL + ',[]{}'
          : BLANKS_BREAKS_NULL;
        if (contains(BLANKS_BREAKS_NULL, ch) ||
            (ch === ':' && contains(valueTerminators, this.peek(length + 1))) ||
            (this.flowLevel && contains(',?[]{}', ch))) {
          break;
        }
        length += 1;
      }
      if (length === 0) break;
      this.allowSimpleKey = false;
      for (let i = 0; i < spaces.length; i++) chunks.push(spaces[i]);
      chunks.push(this.prefix(length));
      this.forward(length);
      endMark = this.getMark();
      spaces = this.scanPlainSpaces(indent, startMark);
      if (spaces === null || spaces.length === 0 || this.peek() === '#' ||
          (!this.flowLevel && this.column < indent)) {
        break;
      }
    }
    return scalarToken(chunks.join(''), true, startMark, endMark, null);
  }

  scanPlainSpaces(indent, startMark) {
    const chunks = [];
    let length = 0;
    while (this.peek(length) === ' ') length += 1;
    const whitespaces = this.prefix(length);
    this.forward(length);
    const ch = this.peek();
    if (contains(BREAKS, ch)) {
      const lineBreak = this.scanLineBreak();
      this.allowSimpleKey = true;
      let prefix = this.prefix(3);
      if ((prefix === '---' || prefix === '...') &&
          contains(BLANKS_BREAKS_NULL, this.peek(3))) {
        return null;
      }
      const breaks = [];
      while (contains(' \r\n  ', this.peek())) {
        if (this.peek() === ' ') {
          this.forward();
        } else {
          breaks.push(this.scanLineBreak());
          prefix = this.prefix(3);
          if ((prefix === '---' || prefix === '...') &&
              contains(BLANKS_BREAKS_NULL, this.peek(3))) {
            return null;
          }
        }
      }
      if (lineBreak !== '\n') chunks.push(lineBreak);
      else if (breaks.length === 0) chunks.push(' ');
      for (let i = 0; i < breaks.length; i++) chunks.push(breaks[i]);
    } else if (whitespaces) {
      chunks.push(whitespaces);
    }
    return chunks;
  }

  scanTagHandle(name, startMark) {
    let ch = this.peek();
    if (ch !== '!') {
      throw new ScannerError('while scanning a ' + name, startMark,
        "expected '!', but found " + pyRepr(ch), this.getMark());
    }
    let length = 1;
    ch = this.peek(length);
    if (ch !== ' ') {
      while (isAnchorChar(ch)) {
        length += 1;
        ch = this.peek(length);
      }
      if (ch !== '!') {
        this.forward(length);
        throw new ScannerError('while scanning a ' + name, startMark,
          "expected '!', but found " + pyRepr(ch), this.getMark());
      }
      length += 1;
    }
    const value = this.prefix(length);
    this.forward(length);
    return value;
  }

  scanTagUri(name, startMark) {
    const chunks = [];
    let length = 0;
    let ch = this.peek(length);
    while (isUriChar(ch)) {
      if (ch === '%') {
        chunks.push(this.prefix(length));
        this.forward(length);
        length = 0;
        chunks.push(this.scanUriEscapes(name, startMark));
      } else {
        length += 1;
      }
      ch = this.peek(length);
    }
    if (length) {
      chunks.push(this.prefix(length));
      this.forward(length);
      length = 0;
    }
    if (chunks.length === 0) {
      throw new ScannerError('while parsing a ' + name, startMark,
        'expected URI, but found ' + pyRepr(ch), this.getMark());
    }
    return chunks.join('');
  }

  scanUriEscapes(name, startMark) {
    const codes = [];
    const mark = this.getMark();
    while (this.peek() === '%') {
      this.forward();
      for (let k = 0; k < 2; k++) {
        if (!isHexDigit(this.peek(k))) {
          throw new ScannerError('while scanning a ' + name, startMark,
            'expected URI escape sequence of 2 hexadecimal numbers, but found ' +
            pyRepr(this.peek(k)), this.getMark());
        }
      }
      codes.push(Number.parseInt(this.prefix(2), 16));
      this.forward(2);
    }
    const decoded = decodeUtf8(codes);
    if (decoded === null) {
      throw new ScannerError('while scanning a ' + name, startMark,
        "'utf-8' codec can't decode byte: invalid start byte", mark);
    }
