  ['v', ''],
  ['f', ' '],
  ['r', ''],
  ['e', ''],
  [' ', ' '],
  ['"', '"'],
  ['\\', '\\'],
  ['/', '/'],
  ['N', ''],
  ['_', ' '],
  ['L', ' '],
  ['P', ' '],
