const path = '/output/lib/scanner.mjs';
let src = fs.readFileSync(path, 'utf8');

// 1. Replace the escape table (it was written with literal control characters,
//    which is not valid JS) with an explicitly escaped version.
const startMarker = 'const ESCAPE_REPLACEMENTS = new Map([';
const endMarker = '\nconst ESCAPE_CODES';
const start = src.indexOf(startMarker);
const end = src.indexOf(endMarker);
if (start < 0 || end < 0) throw new Error('markers not found');

const table = `const ESCAPE_REPLACEMENTS = new Map([
  ['0', '\\u0000'],
  ['a', '\\u0007'],
  ['b', '\\u0008'],
  ['t', '\\u0009'],
  ['\\t', '\\u0009'],
  ['n', '\\u000a'],
  ['v', '\\u000b'],
  ['f', '\\u000c'],
  ['r', '\\u000d'],
  ['e', '\\u001b'],
  [' ', '\\u0020'],
  ['"', '\\u0022'],
  ['\\\\', '\\u005c'],
  ['/', '\\u002f'],
  ['N', '\\u0085'],
  ['_', '\\u00a0'],
  ['L', '\\u2028'],
  ['P', '\\u2029'],
]);
`;

src = src.slice(0, start) + table + src.slice(end + 1);

// 2. Escape the remaining literal special characters.
const map = [
  [String.fromCharCode(0x85), '\\u0085'],
  [String.fromCharCode(0x2028), '\\u2028'],
  [String.fromCharCode(0x2029), '\\u2029'],
  [String.fromCharCode(0xfeff), '\\ufeff'],
  [String.fromCharCode(0xa0), '\\u00a0'],
];
for (const [raw, esc] of map) src = src.split(raw).join(esc);

fs.writeFileSync(path, src);
console.log('patched');

